-- Seed: 90 dummy DJ accounts for testing the "Top 5 House DJs" section and
-- genre filters on the /djs listing page — 30 House, 30 Pop Folk, 30 Commercial.
-- Run once in the Supabase SQL Editor. Safe to re-run (guarded by ON CONFLICT DO
-- NOTHING), except the dj_profiles insert which assumes a clean first run.
-- Same dummy-auth.users trick as seed_djs.sql: inserting into auth.users fires
-- the existing on_auth_user_created trigger, which auto-creates the matching
-- public.profiles row (role + display_name).

insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password,
  email_confirmed_at, created_at, updated_at,
  raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous
) values
